// #472 (i5): literals a paste file meant to set but the live graph does not have. A hand-off that wrote a value only as AutogeneratedDefaultValue (or a value the engine
// dropped on paste) silently becomes the C++ default: BP_HalfHorseZombie's "think every 0.25 s" became 0, "gallop beyond 900 cm" became 0.
// Usage: node t3d_lost_literals.js <paste.txt> <live whole-BP T3D>          -> one line per differing unlinked input pin
//        node t3d_lost_literals.js --json out.json <paste.txt> <live.T3D>   -> also writes [[node, pin, value], ...]
const fs = require('fs');
let args = process.argv.slice(2), jsonOut = null;
if (args[0] === '--json') { jsonOut = args[1]; args = args.slice(2); }
function parse(f, onlyGraph) {
  const t = fs.readFileSync(f, 'utf8'), N = {};
  for (const m of t.matchAll(/Begin Object (?:Class=\S+ )?Name="([^"]+)"([^\n]*)\n([\s\S]*?)\n\s*End Object/g)) {
    const [, name, head, b] = m; if (!b.includes('CustomProperties Pin')) continue;
    if (onlyGraph && /ExportPath/.test(head) && !new RegExp(':' + onlyGraph + '\\.').test(head)) continue;
    const pins = {};
    for (const x of b.matchAll(/CustomProperties Pin \((.*)\)\s*$/gm)) {
      const p = x[1], n = (p.match(/PinName="([^"]+)"/) || [])[1]; if (!n) continue;
      pins[n] = { out: /EGPD_Output/.test(p), exec: /PinCategory="exec"/.test(p), linked: /LinkedTo=\(/.test(p), cat: (p.match(/PinCategory="(\w+)"/) || [])[1],
        dv: (p.match(/[,(]DefaultValue="([^"]*)"/) || [])[1], auto: (p.match(/AutogeneratedDefaultValue="([^"]*)"/) || [])[1], obj: (p.match(/DefaultObject="([^"]*)"/) || [])[1] };
    }
    N[name] = { pins, fn: (b.match(/(?:FunctionReference|VariableReference)=\([^)]*MemberName="(\w+)"/) || [, ''])[1] };
  }
  return N;
}
const norm = v => { if (v === undefined || v === null) return ''; const f = parseFloat(v); return /^-?[\d.]+$/.test(v) && !isNaN(f) ? String(f) : v; };
const S = parse(args[0]), L = parse(args[1], 'EventGraph'); let bad = 0, same = 0, missing = 0; const rows = [];
for (const [n, s] of Object.entries(S)) {
  const l = L[n]; if (!l) { missing++; continue; }
  for (const [pn, p] of Object.entries(s.pins)) {
    if (p.out || p.exec || p.linked || pn === 'self' || pn === 'WorldContextObject') continue;
    const want = p.dv !== undefined ? p.dv : p.auto; if (want === undefined || p.cat === 'object' || p.cat === 'class') continue;
    const q = l.pins[pn]; if (!q || q.linked) continue;
    const have = q.dv !== undefined ? q.dv : q.auto;
    if (norm(want) === norm(have)) { same++; continue; }
    bad++; rows.push([n, pn, want]); console.log(n.padEnd(14), (s.fn + '.' + pn).padEnd(44), 'wanted', String(want).padEnd(14), 'live', have);
  }
}
console.log(args[0].split(/[\\/]/).pop() + ': ' + bad + ' lost, ' + same + ' same, ' + missing + ' nodes not in live');
if (jsonOut) fs.writeFileSync(jsonOut, JSON.stringify(rows));
